<script lang="ts">import Steps from '@fex-design/svelte/primitive/steps-root';import Step from '@fex-design/svelte/primitive/step';import Content from '@fex-design/svelte/primitive/step-content';import Indicator from '@fex-design/svelte/primitive/step-indicator';import Button from '@fex-design/svelte/ui/button';import Card from '@fex-design/svelte/ui/card';let extra=$state(false);const base=[['account','Account'],['profile','Profile'],['review','Review']] as const;let items=$derived(extra?[...base.slice(0,2),['approval','Approval'] as const,base[2]]:base)</script><Card title="Dynamic nodes" description="Stable values keep selection reliable when nodes are inserted or removed."><Steps navigation defaultCurrent="profile">{#each items as item (item[0])}<Step value={item[0]}><Indicator/><Content><strong>{item[1]}</strong></Content></Step>{/each}</Steps><Button class="mt-space-md" onclick={()=>extra=!extra}>{extra?'Remove':'Insert'} approval</Button></Card>
